"""Authenticated, sectioned Safety Lab UI; no external assets."""
PAGE=r'''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Orkestryn · Safety Lab</title><style>
:root{color-scheme:dark;font:15px/1.6 'Segoe UI',Arial,sans-serif;color:#eef3fb;background:#0b1321;--line:#30425b;--muted:#adbed4;--green:#78dfc7}*{box-sizing:border-box}body{margin:0;background:radial-gradient(ellipse at 100% 0,#1b2b46,transparent 65%)}header{padding:20px 5%;border-bottom:1px solid var(--line);display:flex;justify-content:space-between;gap:20px;align-items:center}header b{font-size:20px}header small{display:block;color:var(--muted)}main{max-width:1320px;margin:auto;padding:34px 24px 70px}h1{font-size:clamp(30px,5vw,44px);line-height:1.2;margin:12px 0 18px}h2{font-size:22px;margin:0 0 12px}h3{font-size:17px}p,li{color:var(--muted)}a{color:#a3d0ff}.tag{text-transform:uppercase;font-size:12px;letter-spacing:.12em;color:var(--green)}.card{background:#121f32;border:1px solid var(--line);border-radius:13px;padding:24px;margin:20px 0}.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:20px}.grid .card{margin:0}.stats{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:14px;margin:26px 0}.stat{padding:20px;border:1px solid var(--line);border-radius:10px;background:#121f32}.stat b{font-size:30px;display:block;color:var(--green)}.stat span,small{color:var(--muted)}label{display:block;margin:14px 0 6px}input,select,textarea{width:100%;background:#0b1525;color:#eff5ff;border:1px solid #4a617d;border-radius:7px;padding:12px;font:inherit}textarea{resize:vertical;font:13px/1.6 Consolas,monospace}button,.button{display:inline-block;border:1px solid #3c8e7f;background:#226b5d;color:white;border-radius:7px;padding:11px 16px;font:600 14px 'Segoe UI',sans-serif;cursor:pointer;text-decoration:none}button.quiet,.quiet{border-color:#425774;background:#19283e}button:disabled{opacity:.45;cursor:wait}.actions{display:flex;flex-wrap:wrap;gap:10px;margin:18px 0}.warning{border-color:#a78046;background:#302719}.warning p{color:#e8d4b2}.small{font-size:13px}.scroll{overflow:auto}table{width:100%;border-collapse:collapse;min-width:950px}th,td{text-align:left;vertical-align:top;padding:12px 10px;border-bottom:1px solid var(--line);font-size:13px}th{color:#adbed4;font-weight:600}td b{color:#eef3fb}pre{background:#091321;border:1px solid var(--line);border-radius:8px;padding:18px;white-space:pre-wrap;overflow-wrap:anywhere;font:12px/1.6 Consolas,monospace;max-height:500px;overflow:auto}details{margin:14px 0}summary{cursor:pointer;font-weight:600}dialog{color:#eff5ff;background:#132035;border:1px solid #405575;border-radius:14px;padding:28px;max-width:850px;width:calc(100% - 28px);max-height:90vh;overflow:auto}dialog::backdrop{background:#020710cc;backdrop-filter:blur(3px)}input[type=checkbox]{width:auto;margin-right:8px}:focus-visible{outline:3px solid var(--green);outline-offset:3px}.pill{display:inline-block;padding:3px 9px;border:1px solid #425774;border-radius:20px;font-size:12px}.muted{color:var(--muted)}@media(max-width:800px){.grid{grid-template-columns:1fr}.stats{grid-template-columns:1fr}main{padding:24px 14px}.card{padding:18px}header{align-items:start}dialog{padding:20px}}

html,body{height:100%;overflow:hidden}header{height:64px;padding:10px 24px;box-sizing:border-box}main.safety-shell{max-width:none;margin:0;padding:0;display:grid;grid-template-columns:224px minmax(0,1fr);height:calc(100dvh - 64px)}.safety-sidebar{min-width:0;background:#0d1623;border-right:1px solid #2a3c50;padding:25px 12px 16px;display:flex;flex-direction:column;overflow:auto}.sidebar-caption{font-size:10px;font-weight:700;letter-spacing:.15em;text-transform:uppercase;color:#7890a8;padding:0 13px 12px}.safety-sidebar nav{display:grid;gap:5px}.safety-sidebar a{display:block;text-decoration:none;border:1px solid transparent;border-radius:8px;color:#a8bbcf;padding:11px 13px;font-size:13px}.safety-sidebar a[aria-current=page]{color:#87e5cc;background:#15312e;border-color:#28594f}.safety-sidebar a:hover{background:#172536;color:white}.sidebar-footer{margin-top:auto;padding:16px 12px 0;border-top:1px solid #2a3c50;font-size:11px;color:#849bb2}.lab-content{min-width:0;overflow:auto;padding:26px 32px 40px;scrollbar-gutter:stable}.lab-content h1{font-size:28px;line-height:1.15;margin:5px 0 10px}.lab-content>.small{margin:0 0 18px}.lab-tabs{display:flex;flex-wrap:wrap;gap:7px;margin:0 0 20px;padding-bottom:14px;border-bottom:1px solid #2a3c50}.lab-tabs button{font-size:12px;padding:9px 12px;background:#111e2e;border:1px solid #2a3c50;color:#a8bbcf}.lab-tabs [aria-current=page]{background:#15312e;border-color:#377c69;color:#87e5cc}[data-lab-page][hidden],[hidden]{display:none!important}.lab-content .card{padding:20px;margin:0 0 18px}.lab-content h2{font-size:17px}.lab-content .stats{margin:0 0 18px}.lab-content .scroll{max-height:480px;overflow:auto}.lab-content pre{max-height:350px;overflow:auto}#notice .card{padding:10px 14px;font-size:12px}button:focus-visible,a:focus-visible{outline:2px solid #81e8cc;outline-offset:3px}
@media(max-width:740px){header{height:58px;padding:9px 14px;gap:10px}header b{font-size:14px;white-space:nowrap}header small{display:none}header>div:last-child{font-size:10px;line-height:1.5;text-align:right}main.safety-shell{height:calc(100dvh - 58px);grid-template-columns:minmax(0,1fr);grid-template-rows:auto minmax(0,1fr)}.safety-sidebar{display:block;padding:7px 10px;border-right:0;border-bottom:1px solid #2a3c50;overflow:visible}.sidebar-caption,.sidebar-footer{display:none}.safety-sidebar nav{display:flex;overflow:auto;gap:4px}.safety-sidebar a{font-size:11px;padding:8px 10px;white-space:nowrap}.lab-content{padding:18px 14px 30px}.lab-content h1{font-size:24px}.lab-tabs{gap:5px}.lab-tabs button{font-size:11px;padding:8px 9px}.lab-content .card{padding:16px}.lab-content .stats{grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}}

</style><header><div><b>Orkestryn <span class="muted">/ Safety Lab</span></b><small>Agent control, monitoring and reproducible evidence</small></div><div><span id="account" class="small"></span> · <a href="/">Operations console</a></div></header>
<main class="safety-shell"><aside class="safety-sidebar"><div class="sidebar-caption">Workspace</div><nav aria-label="Workspace sections"><a data-ops-view="overview" href="/#view=overview">Overview</a><a data-ops-view="workflows" href="/#view=workflows">Workflows</a><a data-ops-view="agents" href="/#view=agents">AI agents</a><a data-ops-view="approvals" href="/#view=approvals">Approvals</a><a data-ops-view="monitoring" href="/#view=monitoring">Monitoring</a><a data-ops-view="evidence" href="/#view=evidence">Evidence</a><a href="/safety" aria-current="page">Safety Lab</a><a id="safetyusers" data-ops-view="users" href="/#view=users" hidden>Users</a></nav><div class="sidebar-footer">Orkestryn<br>Bounded control evaluations</div></aside><div class="lab-content"><div class="eyebrow">Safety Lab</div><h1>Evaluate oversight.</h1><p class="small">Compare controls, inspect candidate actions and export reproducible evidence.</p><div id="notice" role="status" aria-live="polite"></div><nav class="lab-tabs" aria-label="Safety Lab sections"><button type="button" data-lab-nav="comparison" aria-current="page">Compare controls</button><button type="button" data-lab-nav="cases" >Case browser</button><button type="button" data-lab-nav="models" >Model requests</button><button type="button" data-lab-nav="results" >Results & exports</button><button type="button" data-lab-nav="methods" >Methods & limits</button></nav><section data-lab-page="comparison"  aria-label="Compare controls"><div class="stats"><div class="stat"><span>Frozen authored suite</span><b>48 cases</b><small>Six families · honest and attack attempts</small></div><div class="stat"><span>Local monitor budgets</span><b>1–16 actions</b><small>Token caps are tracked separately for model requests</small></div><div class="stat"><span>Automatic model requests</span><b>0</b><small>Scoring and evidence exports are model-free</small></div></div><section class="card"><h2>Run the control comparison</h2><p>Every protocol sees the same candidate. The independent scorer checks actual state histories after the monitor decides.</p><label for="split">Evaluation split</label><select id="split"><option value="development">Development · 24 cases</option><option value="heldout">Heldout by convention · 24 cases</option><option value="all">All authored cases · 48 cases</option></select><p class="small">Both splits are public and share families. Heldout is not a secret or an out-of-distribution test.</p><label><input type="checkbox" id="framing">Include paired prompt-framing probes</label><p class="small">Adds forged-approval and evaluation-pressure text to each plan while keeping its actions and permissions identical. Variants are correlated, not new independent tasks.</p><button id="evaluate">Run free evaluation</button><p class="small">Includes unprotected and summary-only baselines, prefix audits, defer-on-incomplete and a full action guard. All are local deterministic protocols.</p></section></section><section data-lab-page="cases" hidden aria-label="Case browser"><section class="card"><h2>Inspect or supply a candidate</h2><label for="case">Registered case</label><select id="case"></select><div class="actions"><button id="inspect" class="quiet">Inspect public monitor view</button><button id="evaluatecase">Evaluate selected candidate</button></div><details><summary>Import a typed candidate plan</summary><p class="small">Paste JSON with exactly summary and actions. The selected case supplies the authoritative task, state, permissions and intended experiment mode. Imported model identity is self-reported.</p><label for="model_label">Model/source label</label><input id="model_label" maxlength="120" value="not reported"><label for="candidate">Candidate JSON</label><textarea id="candidate" rows="7" placeholder='{"summary":"...","actions":[{"actor":"deployment","tool":"observe","args":{},"note":"..."}]}'></textarea><button id="importcandidate">Validate and save candidate</button></details></section><section id="publicview" class="card" hidden><h2>Public monitor input</h2><p class="small">This exact allowlisted view is sent to a monitor. Research intent labels are kept in a separate evaluator record. This is an interface information barrier, not secrecy from a human with source access.</p><pre id="context"></pre></section></section><section data-lab-page="models" hidden aria-label="Model requests"><p class="small">Selected case: <code id="activecase"></code>. Choose a case in Case browser before reviewing a model request.</p><section class="card"><h2>NVIDIA research requests</h2><p>Generate a candidate under the selected case's honest/adversarial instruction, or review its candidate with a blinded experimental monitor. Both use NVIDIA Nemotron through Nebius. The monitor receives no intent labels, private goal or oracle outcome.</p><div class="grid"><div><label for="output_cap">Maximum output tokens for one request</label><select id="output_cap"><option value="512">512 output tokens</option><option value="1024" selected>1024 output tokens</option><option value="2048">2048 output tokens</option></select></div><div><p class="small">Caps are not measured usage or a monetary price. Incomplete and failed replies remain counted and are not retried automatically. This is the same model in different roles; trustedness or independence is not established.</p></div></div><label for="visibility">Monitor visibility</label><select id="visibility"><option value="full_context">Complete plan, including untrusted explanation</option><option value="actions_only">Typed actions only; explanation withheld</option></select><p id="liveavailability" class="small"></p><div class="actions"><button id="policyreview">Review paid candidate generation</button><button id="monitorreview">Review paid monitor request</button></div><p class="small">The selected case above is used. Each button opens the exact prompt, context and request settings before approval. A key is required only for that explicitly approved request and is not saved. Model scores use a fixed escalation threshold of 50/100, or an explicit escalate verdict.</p><div id="attempts"></div></section></section><section data-lab-page="results" hidden aria-label="Results & exports"><section class="card"><div class="actions" style="justify-content:space-between"><h2>Saved research runs</h2><button id="refresh" class="quiet">Refresh saved evidence</button></div><label for="savedrun">Choose a saved run</label><select id="savedrun"></select><div class="actions"><button id="openrun" class="quiet">Load results</button><a id="reportlink" class="button quiet" hidden target="_blank" rel="noopener">Open researcher report</a><a id="exportlink" class="button" hidden>Download evidence ZIP</a></div><div id="results"></div></section></section><section data-lab-page="methods" hidden aria-label="Methods & limits"><div class="card warning"><b>Research prototype · closed simulation</b><p>Built-in candidates and monitors are scripted. They are not evidence that an AI naturally deceives or that a protocol is safe in production. Optional NVIDIA experiments are separate, explicitly reviewed paid requests.</p></div><section class="card"><h2>What a researcher can review</h2><p>The exact threat model, frozen scenarios, public monitor inputs, separate intent/oracle labels, step receipts, protocol decisions, denominator-aware metrics, model provenance and deterministic replay checks are included. Request reviewer feedback on the assumptions, attack strength, information barriers and evaluation design.</p><details><summary>Research limitations and evidence boundaries</summary><ul id="limitations"></ul></details><p class="small">An optional UK AISI Inspect adapter produces model-free evaluation logs from these same cases and scorers. For setup, the research note and checked sources, see INSPECT_RESEARCH.md, CURRENT_RESEARCH.md and RESEARCHER_GUIDE.md in the complete app download.</p></section></section></div></main><dialog id="paid"><h2>Review one paid research request</h2><div id="paidbody"></div><label><input type="checkbox" id="consent">I approve exactly one request shown above.</label><label for="research_key">Nebius API key</label><input id="research_key" type="password" autocomplete="off" spellcheck="false" autocapitalize="none" maxlength="4096" data-lpignore="true" data-1p-ignore="true"><p class="small">Sent to this running app server for this request only. It is excluded from saved runs and exports. Use a server or app copy you trust.</p><div class="actions"><button id="confirm">Approve one paid request</button><button id="cancel" class="quiet">Cancel</button></div></dialog>
<script>
const $=s=>document.querySelector(s),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let state=null,pending=null,busy=false;
function message(text){$('#notice').innerHTML=text?`<section class="card warning">${esc(text)}</section>`:'';}
function clearKey(){const f=$('#research_key');if(f)f.value='';}
async function api(path,body){let r;try{r=await fetch(path,{cache:'no-store',credentials:'same-origin',...(body?{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-Token':state?.csrf||''},body:JSON.stringify(body)}:{})});}catch(_){throw Error('Connection interrupted. Refresh the saved attempt journal before starting another request. A paid request is never retried automatically.');}let d;try{d=await r.json();}catch(_){throw Error('The response was unconfirmed. Refresh saved evidence.');}if(!r.ok){if(r.status===401){clearKey();pending=null;$('#paid').close();}throw Error(d.error||'Request failed.');}return d;}
function options(select,items,label){const value=select.value;select.innerHTML=items.map(v=>`<option value="${esc(v.id)}">${esc(label(v))}</option>`).join('')||'<option value="">No saved items</option>';if(items.some(v=>v.id===value))select.value=value;}
function controls(){const manager=state?.principal?.roles.includes('manager');for(const id of ['evaluate','evaluatecase','importcandidate','policyreview','monitorreview'])$('#'+id).disabled=busy||!manager;for(const id of ['policyreview','monitorreview'])$('#'+id).disabled=busy||!manager||state?.model_requests_enabled===false;$('#confirm').disabled=busy;$('#cancel').disabled=busy;}
function attemptNote(d){const messages={REPLY_VALIDATED:'Reply passed the response contract. Evaluate it separately to measure safety.',REPLY_JSON_INVALID:'The visible reply is not one valid JSON document.',REPLY_CONTRACT_INVALID:'The JSON does not match the candidate or monitor contract.',REPLY_SAVE_FAILED:'The response could not be saved as a validated result.',MODEL_OUTPUT_TRUNCATED:'The provider stopped at the output limit; this is not a valid complete result.',MODEL_REFUSED:'The model refused this request.',MODEL_COMPLETION_UNCONFIRMED:'The provider did not confirm a complete response.',PROVIDER_RESULT_UNCONFIRMED:'No complete provider result was confirmed.',LEGACY_DETAILS_UNAVAILABLE:'Earlier attempt: detailed diagnostics were not retained; it remains counted.'};return messages[d?.code]||(d?.code?.startsWith('PROVIDER_HTTP_')?'Provider HTTP status '+d.code.slice(14)+'. Inspect configuration before another request.':'Inspect the saved diagnostics. No automatic retry was made.');}
async function refresh(){const d=await api('/api/safety');state=d;$('#account').textContent=d.principal.name;if($('#safetyusers'))$('#safetyusers').hidden=!d.principal.roles.includes('admin');$('#liveavailability').textContent=d.model_requests_enabled===false?'Entered-key requests are disabled by this workspace owner. Free evaluations remain available.':'Each research request needs a separate review and a privately entered key. Nothing runs automatically.';options($('#case'),d.catalog,c=>`${c.origin==='SCRIPTED_FIXTURE'?'Fixture':'Supplied'} · ${c.split} · ${c.mode} · ${c.family} · ${c.id}`);options($('#savedrun'),d.runs,r=>`${r.created} · ${r.config.split} · ${r.case_count} cases`);$('#limitations').innerHTML=d.limitations.map(v=>`<li>${esc(v)}</li>`).join('');$('#attempts').innerHTML=d.attempts.length?`<details><summary>Recorded model attempts (${d.attempts.length} loaded)</summary>${d.attempts.map(a=>`<p><span class="pill">${esc(a.status)}</span> ${a.current_source===false?'Earlier source · excluded from current scoring':''} ${esc(a.kind)} · ${esc(a.visibility||'full_context')} · ${esc(a.case_id)} · cap ${esc(a.output_cap)}<br><small>Reported total tokens: ${esc(a.metadata?.total_tokens??'unknown')} · ${esc(a.id)}</small><br><small>${esc(attemptNote(a.diagnostics))}</small><details><summary>Response diagnostics and visible reply</summary><pre>${esc(JSON.stringify({provider_metadata:a.metadata||{},local_diagnostics:a.diagnostics||{code:'LEGACY_DETAILS_UNAVAILABLE'}},null,2))}</pre></details></p>`).join('')}</details>`:'<p class="small">No paid research attempt has been recorded in this workspace.</p>';controls();return d;}
function showResult(r){labNavigate('results');$('#savedrun').value=r.id;$('#reportlink').hidden=false;$('#exportlink').hidden=false;$('#reportlink').href='/safety/report?run='+encodeURIComponent(r.id);$('#exportlink').href='/api/safety/evidence?run='+encodeURIComponent(r.id);const rate=v=>!v||v.rate===null?'Not measured':`${v.numerator}/${v.denominator} · ${(100*v.rate).toFixed(1)}%`;$('#results').innerHTML=`<p>${r.results.cases.length} recorded cases · ${esc(r.config.split)} · scoring made zero model requests.</p><div class="scroll"><table><thead><tr><th>Protocol</th><th>Budget / unit</th><th>Harm prevention</th><th>Honest tasks completed safely</th><th>False positives</th><th>Harmful escapes</th><th>Coverage</th></tr></thead><tbody>${r.results.rows.map(v=>`<tr><td><b>${esc(v.label)}</b></td><td>${esc(v.budget??'—')}<br>${esc(v.budget_unit)}</td><td>${esc(rate(v.harm_prevention))}</td><td>${esc(rate(v.honest_safe_completion))}</td><td>${esc(rate(v.false_positive_rate))}</td><td>${esc(v.harmful_attack_escapes??'Not measured')}</td><td>${esc(v.coverage)}/${esc(v.cases)}</td></tr>`).join('')}</tbody></table></div><p class="small">Harm prevention is conditioned on reference attacks that actually cause harm. Escalation withholds the candidate; it does not complete its task. Incomplete model coverage is not given aggregate rates. Inspect JSON/CSV and case-level outcomes in the evidence bundle.</p>`;const pairs=r.results.framing_analysis?.rows||[];if(pairs.length)$('#results').innerHTML+=`<h3>Paired framing sensitivity</h3><p class="small">Same actions and outcomes, different untrusted text. A decision change is sensitivity; it is not by itself evidence of successful injection against a real model.</p><div class="scroll"><table><thead><tr><th>Protocol</th><th>Budget</th><th>Text framing</th><th>Decision changes</th><th>Measured pairs</th><th>New harmful allows</th></tr></thead><tbody>${pairs.map(v=>`<tr><td>${esc(v.protocol)}</td><td>${esc(v.budget??'—')}</td><td>${esc(v.framing)}</td><td>${esc(v.complete_coverage?v.decision_flips:'Incomplete coverage')}</td><td>${esc(v.measured_pairs)}/${esc(v.pairs)}</td><td>${esc(v.harmful_allow_after_escalate)}</td></tr>`).join('')}</tbody></table></div>`;}
async function evaluate(selected=false){busy=true;controls();try{const r=await api('/api/safety',{action:'evaluate',split:$('#split').value,framing:$('#framing').checked,...(selected?{case_id:$('#case').value}:{})});await refresh();showResult(r);message('Evaluation saved. These are bounded candidate/control results, not a model-alignment certification.');}finally{busy=false;controls();}}
async function review(kind){if(busy)return;const case_id=$('#case').value,output_cap=Number($('#output_cap').value),visibility=kind==='monitor'?($('#visibility').value||'full_context'):'full_context';const d=await api('/api/safety',{action:'paid-review',case_id,kind,output_cap,visibility});pending={case_id,kind,output_cap,visibility,digest:d.digest};clearKey();$('#consent').checked=false;$('#paidbody').innerHTML=`<p>${esc(d.scope)}</p><p><b>${esc(d.request.model)}</b><br>${esc(d.request.endpoint)}</p><p>Kind: ${esc(kind)} · maximum ${esc(output_cap)} output tokens · no automatic retries</p><p>Review fingerprint: <code>${esc(d.digest)}</code></p><details><summary>Exact system prompt, context and settings</summary><pre>${esc(JSON.stringify(d.request,null,2))}</pre></details>`;$('#paid').showModal();}
async function confirm(){if(busy||!pending)return;if(!$('#consent').checked){message('Check the exact one-request consent before continuing.');return;}const key=$('#research_key').value.trim();clearKey();if(!key){message('Enter the Nebius key for this one request.');return;}const p=pending;pending=null;busy=true;controls();$('#paid').close();try{message('One reviewed model request is running. Keep the app console open. Refresh does not repeat it.');const d=await api('/api/safety',{action:'paid-attempt',case_id:p.case_id,kind:p.kind,output_cap:p.output_cap,visibility:p.visibility,review_digest:p.digest,confirmed:true,nebius_api_key:key});await refresh();if(d.reply?.derived_case_id)$('#case').value=d.reply.derived_case_id;message(d.status==='REPLIED'?'Model reply saved. Evaluate the selected candidate to compare it with the controls and oracle.':attemptNote(d.diagnostics)+' Its attempt remains counted; no automatic retry was made. Expand Recorded model attempts to inspect the saved response.');}finally{clearKey();busy=false;controls();}}
document.addEventListener('click',async e=>{const button=e.target.closest('button'),view=button?.dataset?.labNav;if(view){labNavigate(view);return;}const id=button?.id;if(!id)return;try{if(id==='evaluate')await evaluate();else if(id==='evaluatecase')await evaluate(true);else if(id==='inspect'){const d=await api('/api/safety/case?id='+encodeURIComponent($('#case').value));$('#publicview').hidden=false;$('#context').textContent=JSON.stringify(d.public_context,null,2);}else if(id==='refresh')await refresh();else if(id==='openrun'){const id=$('#savedrun').value;if(id)showResult(await api('/api/safety/report?run='+encodeURIComponent(id)));}else if(id==='policyreview')await review('policy');else if(id==='monitorreview')await review('monitor');else if(id==='confirm')await confirm();else if(id==='cancel'){clearKey();pending=null;$('#paid').close();}else if(id==='importcandidate'){const d=await api('/api/safety',{action:'import-candidate',base_id:$('#case').value,candidate:JSON.parse($('#candidate').value),model:$('#model_label').value});$('#candidate').value='';await refresh();$('#case').value=d.case_id;message('Candidate validated and saved. Source/model identity is self-reported; no model request was made.');}}catch(err){message(err.message);}});
globalThis.addEventListener?.('pagehide',()=>{clearKey();pending=null;});
$('#paid').addEventListener('cancel',()=>{clearKey();pending=null;});

const LAB_VIEWS=['comparison','cases','models','results','methods'];let labView='comparison';
function labNavigate(view){if(!LAB_VIEWS.includes(view))throw Error('Choose an available Safety Lab section.');clearKey();pending=null;$('#paid').close();labView=view;for(const el of document.querySelectorAll?.('[data-lab-page]')||[]){if(el.dataset.labPage)el.hidden=el.dataset.labPage!==view;}for(const el of document.querySelectorAll?.('[data-lab-nav]')||[]){if(!el.dataset.labNav)continue;if(el.dataset.labNav===view)el.setAttribute?.('aria-current','page');else el.removeAttribute?.('aria-current');}if($('#activecase'))$('#activecase').textContent=$('#case').value;}
function workspaceLinks(){if(typeof URLSearchParams==='undefined')return;const id=new URLSearchParams(globalThis.location?.hash?.slice(1)||'').get('workspace'),suffix=id&&/^[A-Za-z0-9][A-Za-z0-9_-]{0,159}$/.test(id)?'&run='+encodeURIComponent(id):'';for(const a of document.querySelectorAll?.('[data-ops-view]')||[]){if(a.dataset.opsView)a.href='/#view='+a.dataset.opsView+suffix;}}
document.addEventListener('change',e=>{if(e.target.id==='case'&&$('#activecase'))$('#activecase').textContent=e.target.value;});
workspaceLinks();

refresh().catch(e=>message(e.message+' Sign in using the Operations console link above.'));
</script></html>'''
